// Map YouTube analytics response → analytics_events rows
// Refs: docs/specs/devrel-analytics-stack.md Decision 4
const items = $input.all();
const rows = [];

for (const item of items) {
  const video = item.json;
  const contentId = `youtube:${video.id}`;
  const occurredAt = video.snippet?.publishedAt || new Date().toISOString();

  // View count
  if (video.statistics?.viewCount) {
    rows.push({
      platform: 'youtube',
      content_id: contentId,
      event_type: 'view',
      occurred_at: occurredAt,
      metric_value: parseInt(video.statistics.viewCount, 10),
      metadata: JSON.stringify({ title: video.snippet?.title, channel: $env.YT_CHANNEL_ID })
    });
  }
  // Like count
  if (video.statistics?.likeCount) {
    rows.push({
      platform: 'youtube',
      content_id: contentId,
      event_type: 'like',
      occurred_at: occurredAt,
      metric_value: parseInt(video.statistics.likeCount, 10),
      metadata: JSON.stringify({ title: video.snippet?.title })
    });
  }
  // Comment count
  if (video.statistics?.commentCount) {
    rows.push({
      platform: 'youtube',
      content_id: contentId,
      event_type: 'engagement',
      occurred_at: occurredAt,
      metric_value: parseInt(video.statistics.commentCount, 10),
      metadata: JSON.stringify({ metric: 'comment_count' })
    });
  }
}

return rows.map(row => ({ json: row }));
